document.addEventListener('DOMContentLoaded', () => {
    const cursor = document.querySelector('.cursor');
    const contentType = document.getElementById('contentType');
    const tmdbId = document.getElementById('tmdbId');
    const seasonNumber = document.getElementById('seasonNumber');
    const episodeNumber = document.getElementById('episodeNumber');
    const playButton = document.getElementById('playButton');
    const videoPlayer1 = document.getElementById('videoPlayer1');
    const tvInputs = document.querySelector('.tv-inputs');

    // Initialize cursor
    if (cursor) {
        document.addEventListener('mousemove', (e) => {
            cursor.style.display = 'block';
            cursor.style.left = e.clientX + 'px';
            cursor.style.top = e.clientY + 'px';
        });

        document.addEventListener('mousedown', () => cursor.classList.add('clicking'));
        document.addEventListener('mouseup', () => cursor.classList.remove('clicking'));

        document.querySelectorAll('a, button, input, select').forEach(element => {
            element.addEventListener('mouseenter', () => {
                cursor.style.transform = 'translate(-50%, -50%) scale(1.5)';
                cursor.style.border = '1px solid var(--primary-color)';
                cursor.style.background = 'rgba(139, 92, 246, 0.2)';
            });
            
            element.addEventListener('mouseleave', () => {
                cursor.style.transform = 'translate(-50%, -50%) scale(1)';
                cursor.style.border = '2px solid var(--primary-color)';
                cursor.style.background = 'rgba(139, 92, 246, 0.1)';
            });
        });

        document.addEventListener('mouseout', (e) => {
            if (e.relatedTarget === null) {
                cursor.style.display = 'none';
            }
        });

        document.addEventListener('mouseover', () => {
            cursor.style.display = 'block';
        });
    }

    // Handle content type change
    contentType.addEventListener('change', () => {
        if (contentType.value === 'tv') {
            tmdbId.value = '127532';
            tvInputs.style.display = 'block';
            seasonNumber.value = '1';
            episodeNumber.value = '1';
            tvInputs.style.opacity = '0';
            tvInputs.style.transform = 'translateY(10px)';
            setTimeout(() => {
                tvInputs.style.opacity = '1';
                tvInputs.style.transform = 'translateY(0)';
            }, 10);
        } else {
            tmdbId.value = '558449';
            tvInputs.style.opacity = '0';
            tvInputs.style.transform = 'translateY(10px)';
            setTimeout(() => {
                tvInputs.style.display = 'none';
            }, 300);
        }
    });

    // Auto-play on load
    window.addEventListener('load', () => {
        playButton.click();
    });

    // Handle play button click
    playButton.addEventListener('click', () => {
        if (!tmdbId.value) {
            alert('Please enter a TMDB ID');
            return;
        }

        let embedUrl = '';
        if (contentType.value === 'movie') {
            embedUrl = `http://192.168.8.36:8080/embed/movie/?id=${tmdbId.value}&logo=https://freembed.site/logo.png`;
        } else {
            if (!seasonNumber.value || !episodeNumber.value) {
                alert('Please enter season and episode numbers');
                return;
            }
            embedUrl = `https://freembed.site/embed/tv/?id=${tmdbId.value}&season=${seasonNumber.value}&episode=${episodeNumber.value}&logo=https://freembed.site/logo.png`;
        }

        videoPlayer1.style.opacity = '0';
        videoPlayer1.src = embedUrl;
        videoPlayer1.onload = () => {
            videoPlayer1.style.opacity = '1';
        };
    });

    // Rest of your existing code...
});

function copyToClipboard(button, text) {
    navigator.clipboard.writeText(text).then(() => {
        const toast = document.getElementById('toast');
        toast.textContent = 'Copied successfully!';
        toast.style.display = 'block';
        
        // Change button icon temporarily
        const icon = button.querySelector('i');
        icon.classList.remove('fa-copy');
        icon.classList.add('fa-check');
        
        // Reset button icon after 2 seconds
        setTimeout(() => {
            icon.classList.remove('fa-check');
            icon.classList.add('fa-copy');
        }, 2000);

        // Hide toast after 2.5 seconds
        setTimeout(() => {
            toast.style.display = 'none';
        }, 2500);
    }).catch(err => {
        const toast = document.getElementById('toast');
        toast.textContent = 'Failed to copy text';
        toast.style.display = 'block';
        
        setTimeout(() => {
            toast.style.display = 'none';
        }, 2500);
    });
}